import{_ as a,o as s,c as n,ag as o,j as r,a as e}from"./chunks/framework.KxDd3USm.js";const p=JSON.parse('{"title":"02.1 三级模式与两级映像 ★","description":"","frontmatter":{},"headers":[],"relativePath":"02-数据库系统/01-三级模式与两级映像.md","filePath":"02-数据库系统/01-三级模式与两级映像.md"}'),d={name:"02-数据库系统/01-三级模式与两级映像.md"},g={class:"fig"},h={"data-figure-id":"figure-4",viewBox:"0 0 660 458",width:"100%",style:{"max-width":"660px"},role:"img","aria-label":"三级模式与两级映像结构图。上层是三个外模式：财务视图、人事视图、报表视图。中间是唯一的概念模式，即全体数据的逻辑结构与一张张表的定义。下层是唯一的内模式，即数据在磁盘上的存储方式、索引与压缩。外模式与概念模式之间由外模式模式映像连接，每个外模式各有一个，负责挡住逻辑结构的变化，保证逻辑独立性。概念模式与内模式之间由模式内模式映像连接，全库只有一个，负责挡住存储方式的变化，保证物理独立性。两级映像均由数据库管理系统 DBMS 实现。"};function l(x,t,i,u,c,q){return s(),n("div",null,[t[2]||(t[2]=o('<h1 id="_02-1-三级模式与两级映像-★" tabindex="-1">02.1 三级模式与两级映像 ★ <a class="header-anchor" href="#_02-1-三级模式与两级映像-★" aria-label="Permalink to &quot;02.1 三级模式与两级映像 ★&quot;">​</a></h1><h3 id="为什么需要-三级模式" tabindex="-1">为什么需要&quot;三级模式&quot; <a class="header-anchor" href="#为什么需要-三级模式" aria-label="Permalink to &quot;为什么需要&quot;三级模式&quot;&quot;">​</a></h3><p>数据库是被很多应用程序<strong>共享</strong>的：财务程序、人事程序、报表工具都要读同一批数据，但它们各只关心自己那一块，而且谁都不希望&quot;存储结构一改、我的程序就得重写&quot;。为此数据库把数据组织分成三个视角、配上两层&quot;翻译层&quot;，把<strong>变化隔离</strong>在各自层内——这就是考&quot;独立性&quot;的全部动机。</p><h3 id="三级模式-数据的三个抽象级别" tabindex="-1">三级模式：数据的三个抽象级别 <a class="header-anchor" href="#三级模式-数据的三个抽象级别" aria-label="Permalink to &quot;三级模式：数据的三个抽象级别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>别名</th><th>看到什么</th><th>例子</th></tr></thead><tbody><tr><td>外模式</td><td>用户模式 / 子模式</td><td>某类用户看到的部分数据</td><td>一个视图、一张报表用的字段</td></tr><tr><td>概念模式</td><td>模式 / 逻辑模式</td><td>全体数据的逻辑结构</td><td>一张张表的定义</td></tr><tr><td>内模式</td><td>存储模式</td><td>数据在磁盘上怎么存</td><td>索引、压缩、存储顺序</td></tr></tbody></table><p>三者是<strong>同一个数据库的三个视角</strong>，不是三份数据：外模式可以有多个（每类用户一个），模式与内模式各只有一个。</p>',6)),r("figure",g,[(s(),n("svg",h,[...t[0]||(t[0]=[o('<text class="side" x="30" y="22">高层 · 面向用户</text><rect class="box" x="30" y="32" width="180" height="52" rx="9"></rect><text class="t3" x="120" y="54">外模式 1</text><text class="t3s" x="120" y="71">财务视图</text><rect class="box" x="240" y="32" width="180" height="52" rx="9"></rect><text class="t3" x="330" y="54">外模式 2</text><text class="t3s" x="330" y="71">人事视图</text><rect class="box" x="450" y="32" width="180" height="52" rx="9"></rect><text class="t3" x="540" y="54">外模式 3</text><text class="t3s" x="540" y="71">报表视图</text><rect class="map" x="120" y="118" width="420" height="44" rx="8"></rect><text class="mapt" x="330" y="137">外模式 / 模式映像</text><text class="mapw" x="330" y="153">每个外模式各有一个</text><path class="edge" d="M120 84 V118"></path><path class="edge" d="M330 84 V118"></path><path class="edge" d="M540 84 V118"></path><text class="ind" x="330" y="184">挡住逻辑结构的变化，保证「逻辑独立性」</text><rect class="boxcore" x="120" y="196" width="420" height="60" rx="9"></rect><text class="t3" x="330" y="221">概念模式（模式 / 逻辑模式）</text><text class="t3s" x="330" y="240">全体数据的逻辑结构 · 一张张表的定义 · 全库唯一</text><rect class="map" x="120" y="288" width="420" height="44" rx="8"></rect><text class="mapt" x="330" y="307">模式 / 内模式映像</text><text class="mapw" x="330" y="323">全库只有一个</text><path class="edge" d="M330 256 V288"></path><text class="ind" x="330" y="354">挡住存储方式的变化，保证「物理独立性」</text><path class="edge" d="M330 332 V378"></path><rect class="boxcore" x="120" y="378" width="420" height="60" rx="9"></rect><text class="t3" x="330" y="403">内模式（存储模式）</text><text class="t3s" x="330" y="422">磁盘存储方式 · 索引 · 压缩 · 全库唯一</text><text class="side" x="30" y="452">低层 · 面向机器</text>',30)])])),t[1]||(t[1]=r("figcaption",null,[e('三级模式被两级映像"夹"在中间：外模式可有多个，模式与内模式各一个。'),r("strong",null,"变化发生在哪一层，就由连着该层的那半层映像挡住"),e('——这就是"独立性"的来源。')],-1))]),t[3]||(t[3]=o('<h3 id="两级映像-靠-翻译层-吃掉变化" tabindex="-1">两级映像：靠&quot;翻译层&quot;吃掉变化 <a class="header-anchor" href="#两级映像-靠-翻译层-吃掉变化" aria-label="Permalink to &quot;两级映像：靠&quot;翻译层&quot;吃掉变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>映像</th><th>连接的两层</th><th>保证的独立性</th><th>数量</th><th>白话</th></tr></thead><tbody><tr><td><strong>外模式/模式映像</strong></td><td>外模式 ↔ 模式</td><td><strong>逻辑独立性</strong></td><td>每个外模式一个</td><td>表的逻辑结构变了（加字段），此应用看到的视图不变</td></tr><tr><td><strong>模式/内模式映像</strong></td><td>模式 ↔ 内模式</td><td><strong>物理独立性</strong></td><td>全库一个</td><td>换了存储方式（加索引、换顺序），表定义和程序都不用改</td></tr></tbody></table><p><strong>两个必须记牢的规范定义（选择题按这句判）</strong>：</p><ul><li><strong>物理独立性</strong>：当数据库的<strong>内模式</strong>改变时，通过对<strong>模式/内模式映像</strong>的相应调整，可以使<strong>模式保持不变</strong>，从而<strong>应用程序也不变</strong>。</li><li><strong>逻辑独立性</strong>：当数据库的<strong>模式</strong>改变时，通过对<strong>外模式/模式映像</strong>的相应调整，可以使<strong>外模式保持不变</strong>，从而<strong>应用程序也不变</strong>。</li></ul><p>注意两句话的落点：物理独立性是&quot;<strong>内模式变 → 模式不变</strong>&quot;，逻辑独立性是&quot;<strong>模式变 → 外模式不变</strong>&quot;。&quot;应用程序不变&quot;是两者的共同结果，<strong>不能用来区分</strong>它们——区分靠的是<strong>变化发生在哪一层</strong>。</p><h3 id="三个高频陷阱" tabindex="-1">三个高频陷阱 <a class="header-anchor" href="#三个高频陷阱" aria-label="Permalink to &quot;三个高频陷阱&quot;">​</a></h3><table tabindex="0"><thead><tr><th>陷阱</th><th>正解</th></tr></thead><tbody><tr><td><strong>两级映像由谁实现？</strong></td><td><strong>由 DBMS 实现</strong>（DBMS 在模式定义里登记映像关系）。不是 DBA 手工维护，也不是应用程序自己实现——选项里出现&quot;由应用程序实现映像&quot;必错</td></tr><tr><td><strong>有没有&quot;三级映像&quot;？</strong></td><td><strong>没有</strong>。模式之间只有<strong>两级映像</strong>，不存在&quot;外模式/内模式映像&quot;；见到这个词直接排除</td></tr><tr><td><strong>外模式/内模式各几个？</strong></td><td>外模式<strong>可多个</strong>、模式与内模式<strong>各一个</strong>，所以外模式/模式映像可多个、模式/内模式映像只有一个</td></tr></tbody></table><h3 id="正例与反例演示" tabindex="-1">正例与反例演示 <a class="header-anchor" href="#正例与反例演示" aria-label="Permalink to &quot;正例与反例演示&quot;">​</a></h3><p><strong>正例（这么说是对的）</strong>：</p><ul><li>&quot;把数据文件从顺序存储改成链式存储、或加了个索引，模式不变、应用程序也不用改&quot;——变化发生在<strong>内模式</strong>层，由<strong>模式/内模式映像</strong>吸收，所以是<strong>物理独立性</strong>。</li><li>&quot;表里新增了一个字段，应用程序不用改&quot;——变化发生在<strong>模式</strong>层，由<strong>外模式/模式映像</strong>吸收，所以是<strong>逻辑独立性</strong>。</li></ul><p><strong>反例（这么说是错的，最容易被题目钓住）</strong>：</p><table tabindex="0"><thead><tr><th>错误说法</th><th>错在哪里</th></tr></thead><tbody><tr><td>&quot;换存储方式，靠<strong>外模式/模式映像</strong>保证物理独立性&quot;</td><td><strong>张冠李戴</strong>：物理层的变化必须由<strong>模式/内模式映像</strong>接住；外模式/模式映像管的是逻辑层</td></tr><tr><td>&quot;表加字段后程序不用改，这叫<strong>物理独立性</strong>&quot;</td><td><strong>概念混淆</strong>：表结构是<strong>逻辑</strong>结构，对应<strong>逻辑</strong>独立性；物理独立性只跟磁盘上的存储方式有关</td></tr><tr><td>&quot;加索引是物理独立性，那加字段也是物理独立性&quot;</td><td><strong>过度推广</strong>：索引属内模式、字段属模式，两者对应不同的独立性，不能类推</td></tr><tr><td>&quot;存在<strong>外模式/内模式映像</strong>&quot;</td><td><strong>无中生有</strong>：映像只有两级，跨过中间模式的那一层不存在</td></tr><tr><td>&quot;映像由<strong>应用程序</strong>自己维护&quot;</td><td><strong>主体错位</strong>：映像由 <strong>DBMS</strong> 实现与维护</td></tr></tbody></table><p><strong>判断口诀</strong>：<strong>变化发生在哪一层 → 就由连着该层的那半层映像去挡</strong>——外模式/模式映像连着模式这一侧，管逻辑；模式/内模式映像连着内模式这一侧，管物理。更保险的反查法是<strong>看题干&quot;保证了什么&quot;</strong>：只说<strong>应用不用改</strong> → 逻辑独立性；连<strong>表定义都不用改</strong> → 物理独立性。别按字面想&quot;逻辑独立性 = 跟逻辑有关，所以发生在内模式&quot;，逻辑独立性的意思是<strong>逻辑结构变了也波及不到应用</strong>。</p><p><strong>应试动作</strong>：背下&quot;外模式/模式映像 ↔ 逻辑独立性，模式/内模式映像 ↔ 物理独立性&quot;这组配对，再记住&quot;<strong>两级映像、由 DBMS 实现</strong>&quot;这两个要点，最后看题干描述的变化发生在<strong>哪一层</strong>、保证了<strong>什么不变</strong>，即可定案。</p>',14))])}const b=a(d,[["render",l]]);export{p as __pageData,b as default};
